"""Reproducible synthetic market data for Demo mode.

Design goals
------------
* **Deterministic**: identical output on every run and every machine.
  ``zlib.crc32`` (not Python's salted ``hash``) derives per-asset parameters
  and RNG seeds, so results are reproducible across processes.
* **Offline**: no network access, no API keys.
* **Honest**: series are generated by geometric Brownian motion and are
  always surfaced in the UI with a "SIMULATED / Demo data" label.

The GBM model for asset ``i``:

    log(P_t / P_{t-1}) ~ N( (mu_i - 0.5 * sigma_i^2) * dt ,  sigma_i * sqrt(dt) )

with ``dt = 1 / 252`` and prices on a Monday-Friday calendar.
"""
from __future__ import annotations

import datetime as _dt
import zlib
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np
import pandas as pd

from config import TRADING_DAYS

DEFAULT_SEED = 20240517
BASE_PRICE = 100.0


def asset_parameters(ticker: str) -> Tuple[float, float]:
    """Deterministic (annual drift, annual volatility) for a ticker.

    Drift in [3 %, 13 %], volatility in [9 %, 38 %], with higher-volatility
    assets given a slightly lower drift so demo portfolios behave plausibly.
    """
    key = zlib.crc32(str(ticker).encode("utf-8"))
    rng = np.random.default_rng([DEFAULT_SEED, key])
    mu = float(rng.uniform(0.03, 0.13))
    sigma = float(rng.uniform(0.09, 0.38))
    return mu, sigma


def base_price(ticker: str) -> float:
    """Deterministic starting price in a plausible range (simulated only)."""
    key = zlib.crc32(f"{ticker}|price".encode("utf-8"))
    rng = np.random.default_rng([DEFAULT_SEED + 1, key])
    return float(rng.uniform(20.0, 480.0))


def trading_days(start: _dt.date, end: _dt.date) -> pd.DatetimeIndex:
    if end < start:
        raise ValueError("end date must not be before start date")
    return pd.bdate_range(pd.Timestamp(start), pd.Timestamp(end))


def demo_prices(
    tickers: Sequence[str],
    start: _dt.date,
    end: _dt.date,
    *,
    seed: int = DEFAULT_SEED,
) -> pd.DataFrame:
    """Deterministic simulated close prices for ``tickers``.

    Raises ``ValueError`` if the date range yields fewer than two sessions.
    """
    tickers = [str(t) for t in dict.fromkeys(tickers)]  # de-duplicate, keep order
    if not tickers:
        raise ValueError("no tickers supplied")
    dates = trading_days(start, end)
    if len(dates) < 2:
        raise ValueError("the selected period contains fewer than two trading days")

    dt = 1.0 / TRADING_DAYS
    frame = pd.DataFrame(index=dates)
    for ticker in tickers:
        mu, sigma = asset_parameters(ticker)
        key = zlib.crc32(str(ticker).encode("utf-8"))
        rng = np.random.default_rng([seed, key])
        shocks = rng.normal(loc=(mu - 0.5 * sigma ** 2) * dt, scale=sigma * np.sqrt(dt),
                            size=len(dates))
        log_prices = np.log(base_price(ticker)) + np.cumsum(shocks)
        frame[ticker] = np.exp(log_prices)
    frame.index.name = "date"
    return frame.round(4)


def demo_prices_for(
    assets: Iterable[Dict[str, str]],
    start: _dt.date,
    end: _dt.date,
) -> pd.DataFrame:
    """Convenience wrapper taking asset-metadata dicts."""
    return demo_prices([a["ticker"] for a in assets], start, end)


def is_simulated() -> bool:
    """Every demo price is simulated by construction."""
    return True
